INSERT INTO `receita` (`id_receita`, `nome_receita`, `numeroPorcao_receita`, `tipoPorcao_receita`, `tempoPreparoHora_receita`, `tempoPreparoMinuto_receita`, `modoPreparo_receita`, `imagem_receita_blob`, `imagem_receita_mime`, `categoria_receita`, `fk_id_usuario`) VALUES
(1, 'Soda Italiana Cremosa', 2.000, 1, 0, 5, '1. Preencha um copo alto com ¾ de xícara de gelo.\r\n2. Despeje o xarope sobre o gelo.\r\n3. Adicione a água com gás.\r\n4. Finalize com creme de leite e/ou chantilly.\r\n5. Misture e aproveite!', , 'image/png', 25, 1);
INSERT INTO `receita` (`id_receita`, `nome_receita`, `numeroPorcao_receita`, `tipoPorcao_receita`, `tempoPreparoHora_receita`, `tempoPreparoMinuto_receita`, `modoPreparo_receita`, `imagem_receita_blob`, `imagem_receita_mime`, `categoria_receita`, `fk_id_usuario`) VALUES
(2, 'Brigadeiro de Pistache', 25.000, 1, 8, 20, '1. Em uma panela, coloque o Leite Moça, o Creme de Leite, o pistache triturado, a pasta de pistache e a glucose de milho e misture bem.\r\n2. Leve ao fogo médio, mexendo sempre, por cerca de 8 minutos, ou até desgrudar do fundo da panela.\r\n3. Coloque em um prato untado com manteiga e deixe descansar por cerca de 8 horas.\r\n4. Com as mãos untadas, enrole em forma de brigadeiros, passe no pistache triturado e sirva.', , 'image/png', 29, 1);
INSERT INTO `receita` (`id_receita`, `nome_receita`, `numeroPorcao_receita`, `tipoPorcao_receita`, `tempoPreparoHora_receita`, `tempoPreparoMinuto_receita`, `modoPreparo_receita`, `imagem_receita_blob`, `imagem_receita_mime`, `categoria_receita`, `fk_id_usuario`) VALUES
(3, 'Brigadeiro Casadinho de Morango e Ninho', 12.000, 8, 1, 45, '1. Em uma panela, adicione o leite condensado, o leite em pó e a manteiga para fazer o brigadeiro de Ninho.\r\n\r\n2. Cozinhe em fogo baixo, mexendo sempre até que a mistura desgrude do fundo da panela (ponto de brigadeiro).\r\n\r\n3. Retire o brigadeiro de Ninho do fogo e deixe esfriar até estar em temperatura ambiente para modelar.\r\n\r\n4. Em outra panela, adicione o leite condensado, o chocolate branco, a manteiga e o pó para preparo de morango para fazer o brigadeiro de morango.\r\n\r\n5. Cozinhe em fogo baixo, mexendo até que a mistura desgrude do fundo da panela (mesmo ponto do brigadeiro de Ninho).\r\n\r\n6. Retire o brigadeiro de morango do fogo e deixe esfriar até atingir a temperatura ideal para modelar.\r\n\r\n7. Com a ajuda de uma balança, pese 4 gramas de brigadeiro de Ninho e faça uma bolinha.\r\n\r\n8. Pese 4 gramas de brigadeiro de morango e faça outra bolinha.\r\n\r\n9. Achate as bolinhas separadamente antes de enrolá-las para garantir uma divisão perfeita no meio do doce.\r\n\r\n10. Una as duas partes (Ninho e morango) e enrole para formar o casadinho.\r\n\r\n11. Passe os casadinhos imediatamente no açúcar refinado, enquanto ainda há gordura ativada para que o açúcar adira bem à superfície.\r\n\r\n12. Coloque os casadinhos em forminhas, cuidando para que a divisão entre os dois sabores (Ninho e morango) fique bem no meio do doce.\r\n\r\n13. Os casadinhos estão prontos para serem servidos!\r\n\r\nDica: O truque para uma divisão perfeita entre os dois sabores é achatar as bolinhas antes de enrolá-las. Isso garante que a separação fique visível e o resultado seja esteticamente bonito.', , 'image/png', 29, 1);
INSERT INTO `receita` (`id_receita`, `nome_receita`, `numeroPorcao_receita`, `tipoPorcao_receita`, `tempoPreparoHora_receita`, `tempoPreparoMinuto_receita`, `modoPreparo_receita`, `imagem_receita_blob`, `imagem_receita_mime`, `categoria_receita`, `fk_id_usuario`) VALUES
(4, 'Brigadeiro Romeu e Julieta', 12.000, 1, 0, 90, '1. Em uma panela, misture o Leite Moça, o  Creme de Leite, o queijo ralado e o chocolate branco picado. Leve ao fogo médio, mexendo sempre, por cerca de 8-10 minutos até que o brigadeiro fique no ponto de enrolar.\r\n2. Transfira para um prato untado, cubra com plástico-filme e deixe esfriar por completo.\r\n3. Após, porcione quantidades do brigadeiro, faça bolinhas, abra-as na palma da mão e recheie-as com alguns pedaços da goiabada picada. Feche e boleie para obter um brigadeiro. Passe-os brigadeiros no açúcar cristal, coloque-os em forminhas próprias e sirva.', , 'image/png', 29, 1);
INSERT INTO `receita` (`id_receita`, `nome_receita`, `numeroPorcao_receita`, `tipoPorcao_receita`, `tempoPreparoHora_receita`, `tempoPreparoMinuto_receita`, `modoPreparo_receita`, `imagem_receita_blob`, `imagem_receita_mime`, `categoria_receita`, `fk_id_usuario`) VALUES
(5, 'Hot Roll California', 36.000, 8, 0, 90, '1. Reúna os ingredientes para fazer esse hot roll califórnia, uma variação deliciosa de sushi. Pegue também uma esteira de bambu e mantenha uma tigela com água para umedecer os dedos durante o processo;\r\n2. Cozinhe o arroz para sushi conforme as instruções do pacote. Após cozido, tempere com vinagre de arroz, açúcar e sal. Deixe esfriar;\r\n3. Descasque a manga e pique em fatias finas. Lave e pique o pepino em fatias finas. Pique também o kani em fatias finas. Tente deixar todos os ingredientes fatiados com a mesma espessura;\r\n4. Cubra a esteira para sushi com filme plástico e coloque em cima a folha de alga nori;\r\n5. Umedeça as mãos com água para evitar que o arroz grude e espalhe uma camada de arroz sobre a alga, deixando cerca de 1 cm de alga livre na borda superior;\r\n6. Coloque tiras de pepino, manga e kani sobre o arroz, posicione horizontalmente e um pouco abaixo do centro;\r\n7. Use a esteira de bambu para enrolar o sushi de forma firme, pressionando suavemente para compactar os ingredientes. Umedeça, levemente a borda da alga com um pouco de água para facilitar o fechamento;\r\n8. Em uma recipiente, misture a farinha e a água. Em outro recipiente, coloque a farinha panko;\r\n9. Mergulhe cada peça na massa até ficar completamente envolvida. Em seguida, passe cada peça na farinha panko;\r\n10. Numa panela média, coloque o óleo e leve ao fogo alto para aquecer. Quando o óleo estiver quente, abaixe o fogo;\r\n11. Adicione as peças no óleo e deixe que fritem até que estejam douradas e crocantes. Com uma escumadeira, retire cada peça e coloque em um prato forrado com papel-toalha para remover o excesso de óleo;\r\n12. Sirva o hot roll california quente, acompanhado de shoyu, wasabi ou molho tarê, se desejar. Bom apetite!', , 'image/jpeg', 3, 1);
INSERT INTO `receita` (`id_receita`, `nome_receita`, `numeroPorcao_receita`, `tipoPorcao_receita`, `tempoPreparoHora_receita`, `tempoPreparoMinuto_receita`, `modoPreparo_receita`, `imagem_receita_blob`, `imagem_receita_mime`, `categoria_receita`, `fk_id_usuario`) VALUES
(6, 'Mousse de Chocolate', 6.000, 1, 0, 30, '1. Reúna todos os ingredientes da mousse de chocolate;\r\n2. Em um recipiente, coloque o chocolate e derreta em banho-maria ou no micro-ondas (de 30 em 30 segundos);\r\n3. Assim que o chocolate estiver totalmente derretido, acrescente o creme de leite e misture até obter uma ganache de chocolate;\r\n4. Em uma batedeira ou à mão, bata as claras de ovo até obter as claras em neve;\r\n5. Depois, adicione as claras em neve ao recipiente com a ganache de chocolate. Misture delicadamente, fazendo movimento circulares, até obter um creme homogêneo;\r\n6. Transfira a mousse para um refratário, cubra com plástico filme ou tampa e leve à geladeira por cerca de 2 horas;\r\n7. Agora é só servir gelado. Bom apetite!\r\n', , 'image/png', 29, 1);
INSERT INTO `receita` (`id_receita`, `nome_receita`, `numeroPorcao_receita`, `tipoPorcao_receita`, `tempoPreparoHora_receita`, `tempoPreparoMinuto_receita`, `modoPreparo_receita`, `imagem_receita_blob`, `imagem_receita_mime`, `categoria_receita`, `fk_id_usuario`) VALUES
(81, 'Creme da Noviça', 8.000, 1, 2, 10, '1. Dilua as gelatinas na água fervendo, coloque no liquidificador o restante dos ingredientes e as gelatinas dissolvidas em água quente.\r\n\r\n2. Bata bem.\r\n\r\n3. Coloquem em uma forma média de pudim.\r\n\r\n4. Leve à geladeira por mais ou menos 2 horas.\r\n\r\n5. Depois de firme é só desenformar e servir.', , 'image/png', 29, 1);
INSERT INTO `receita` (`id_receita`, `nome_receita`, `numeroPorcao_receita`, `tipoPorcao_receita`, `tempoPreparoHora_receita`, `tempoPreparoMinuto_receita`, `modoPreparo_receita`, `imagem_receita_blob`, `imagem_receita_mime`, `categoria_receita`, `fk_id_usuario`) VALUES
(82, 'Creme da Noviça Sem Lactose', 8.000, 1, 2, 10, '1. Dilua as gelatinas na água fervendo, coloque no liquidificador o restante dos ingredientes e as gelatinas dissolvidas em água quente.\r\n\r\n2. Bata bem.\r\n\r\n3. Coloquem em uma forma média de pudim.\r\n\r\n4. Leve à geladeira por mais ou menos 2 horas.\r\n\r\n5. Depois de firme é só desenformar e servir.', , 'image/png', 23, 1);
INSERT INTO `receita` (`id_receita`, `nome_receita`, `numeroPorcao_receita`, `tipoPorcao_receita`, `tempoPreparoHora_receita`, `tempoPreparoMinuto_receita`, `modoPreparo_receita`, `imagem_receita_blob`, `imagem_receita_mime`, `categoria_receita`, `fk_id_usuario`) VALUES
(88, 'Pão de Ló', 8.000, 9, 0, 60, '1. Reúna todos os ingredientes;\r\n2. Um recipiente com ovos e açúcar.\r\n3. Coloque os ovos e o açúcar na batedeira;\r\n4. Um recipiente com um creme de ovos e açúcar.\r\n5. Bata em velocidade baixa e gradualmente, vá aumentando a velocidade até chegar ao máximo até que o creme que se forma quase transborde;\r\n6. Um recipiente com farinha e creme de ovos e açúcar.\r\n7. Desligue a batedeira e peneire a farinha na massa e, com uma espátula, misture bem a farinha na massa até incorporar;\r\n8. Uma assadeira com a massa crua do pão de ló.\r\n9. Despeje a massa em uma forma (26 cm de diâmetro) forrada com papel manteiga e leve ao forno preaquecido a 180 °C por 45 minutos.\r\n10. Um bolo pão de ló com uma fatia sendo retirada.\r\n11. Desenforme, ainda morno, cuidadosamente e sirva. Bom apetite!', , 'image/png', 36, 1);
